import click

class MyCommand(click.Command):
    pass

class MyGroup(click.Group):
    command_class = MyCommand
    group_class = None

@click.group(cls=MyGroup)
def cli():
    pass

# concise form
@cli.command
def a():
    pass

# called form
@cli.command()
def b():
    pass

# explicit override
@cli.command(cls=click.Command)
def c():
    pass

print(type(a).__name__, type(b).__name__, type(c).__name__)
assert isinstance(a, MyCommand)
assert isinstance(b, MyCommand)
assert type(c) is click.Command
print("OK")
EOF
